var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original code returned n * y for 'y', 'yr', 'yrs', 'year', 'years'
    // The patch removed this, so '1y' should now be parsed as '1w' (weeks)
    // Original: ms('1y') === 31557600000
    // Patched:  ms('1y') === 604800000 (1 week)
    const original = 31557600000;
    const patched = 604800000;
    const result = ms('1y');
    assert.strictEqual(result, patched, 'Parsing "1y" should now return 604800000 (1 week) in the patched version');
  });
});

